get_category_page.code:
final response = await client.categoryPage.getCategoryPage();
final categoryPage = (response.map as Map)['category_page'] as Map;
print(categoryPage['category_information']);
print(categoryPage['product_information']);

patch_category_page.code:
final response = await client.categoryPage.patchCategoryPage({
  'category_page': {
    'category_information': {
      'show_description': true,
      'subcategory': {'per_page': 24},
    },
  },
});
final categoryPage = (response.map as Map)['category_page'] as Map;
print(categoryPage['category_information']);

get_category_page_section.code:
final response =
    await client.categoryPage.getCategoryPageSection('category_information');
final section = (response.map as Map)['category_information'] as Map;
print(section['show_description']);
print(section['subcategory']);

patch_category_page_section.code:
final response = await client.categoryPage
    .patchCategoryPageSection('category_information', {
  'category_information': {'show_description': true},
});
final section = (response.map as Map)['category_information'] as Map;
print(section['show_description']);
